def drop_source_columns(apps,schema_editor):
    for name,fields in SOURCE_FIELDS.items():
        model=apps.get_model('erp_base',name)
        columns=[model._meta.get_field(field).column for field in fields]
        quote=schema_editor.quote_name
        schema_editor.execute('ALTER TABLE '+quote(model._meta.db_table)+' '+', '.join('DROP COLUMN '+quote(column) for column in columns))


def restore_source_columns(apps,schema_editor):
    for name,fields in SOURCE_FIELDS.items():
        model=apps.get_model('erp_base',name)
        for field in fields:schema_editor.add_field(model,model._meta.get_field(field))


